#!/usr/bin/env node
// SPDX-License-Identifier: MIT
// One spelling for reaching a GObject library at RUNTIME: `gi://Ns?version=x`.
//
// WHAT THIS IS ABOUT. `@girs/*` is the TYPE vocabulary — generated by ts-for-gir,
// consumed by `tsc`, and with no runtime of its own. `gi://` is the loader. Both
// spellings appear in the tree, and a reader cannot tell from the import line which one
// a file meant: `import Gtk from '@girs/gtk-4.0'` typechecks whether the code calls
// `Gtk.init()` or only writes `Gtk.Widget` in a type position, and only the first is a
// runtime dependency. So the rule is stated once here rather than decided per file:
// a value import comes from `gi://`, a type import from `@girs/*`.
//
// WHY A GATE AND NOT A CONVENTION. The tree was 62% converted when this landed (451
// `gi://` imports against 282 remaining `@girs/*` value imports) and a half-migrated
// tree with no gate converges on whichever spelling the last author copied from.
//
// HOW IT DEGRADES, which is the part worth designing. A ratchet over a COUNT would let
// any converted file be un-converted as long as another was converted in the same
// commit. So the pending work is named by DIRECTORY instead, and the list is checked in
// BOTH directions: an offender outside the list fails, and a listed directory with no
// offenders left ALSO fails, naming itself for deletion. A list that cannot go stale is
// a list nobody has to trust.
//
// WHAT IT DOES NOT CHECK: whether a `gi://` import is the RIGHT namespace or version.
// `check-gi-import-versions.mjs` owns the version half.

import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';

import { GIRS_RUNTIME_IMPORT_VECTORS } from './girs-runtime-import-fixtures.mjs';

/**
 * Directories whose `@girs/*` runtime imports have NOT been converted yet.
 *
 * Shrinks per pull request; an entry that no longer has an offender fails the gate, so
 * this cannot outlive the work it describes. Add nothing here — a NEW file writes
 * `gi://`.
 */
const PENDING = [
    'packages/framework/devtools-browser/',
    'packages/framework/devtools-mcp/',
    'packages/framework/webgl/',
    'packages/gjs/utils/',
    'packages/node/',
    'packages/web/',
    'tests/',
];

/**
 * Files worth reading — SOURCE AND PROSE.
 *
 * Documentation is in scope because a reader copies from it: a guide whose fenced
 * example still writes `@girs/*` teaches the spelling the tree is retiring, and the
 * examples outlive the migration that changed the code. All 79 doc occurrences went in
 * the same commit as the code for that reason.
 *
 * Prose ABOUT the vocabulary is untouched by construction: the reader only matches a
 * line that IS an import statement, so "`@girs/*` is the type vocabulary" is not one,
 * and a type import — the form the docs should keep showing — is excluded below.
 */
const SOURCE = /\.(ts|tsx|mts|cts|js|mjs|cjs|md|mdx)$/;
const GENERATED = /(^|\/)(lib|dist|build|node_modules|tmp|\.gi-tests)\//;
/** This gate's own vectors, which carry the offending shape as data. */
const FIXTURES = 'scripts/girs-runtime-import-fixtures.mjs';

/**
 * Every RUNTIME import of an `@girs/*` package in `source`.
 *
 * A runtime import is one that BINDS A VALUE: a default binding, a namespace binding,
 * named bindings that are not `type`-qualified, or a dynamic `import(…)`. Not:
 * `import type …`, `import { type X }`, `export … from`, or a bare side-effect import,
 * which binds nothing.
 *
 * WHOLE TEXT, NOT LINE BY LINE, and that is the whole repair. The first version read one
 * line at a time and was therefore blind to every import list this repository's own
 * formatter had wrapped — eight live value bindings in `gtk-host`'s generator spec, from
 * a directory that is not pending, over which the gate printed OK. A reader whose scope
 * is narrower than the language it reads fails silently by construction.
 *
 * A SUBPATH IS NOT A NAMESPACE. Only the bare package maps to a `gi://` specifier;
 * `@girs/gtk-4.0/vocabulary` is generated data (ADR 0029) with no counterpart at all.
 * Stated as a boundary rather than an exemption list, so it also holds for the next
 * subpath somebody adds.
 *
 * COMMENTS. The static form must begin a line, which is what keeps a specifier quoted in
 * PROSE out — the rule this file's own docblocks depend on. The dynamic form appears
 * mid-expression and cannot use that, so a match is dropped when what precedes it on its
 * line opens a line comment or continues a block one.
 *
 * A COMMENTED-OUT import statement is therefore still reported, and that is deliberate:
 * a commented `@girs` import is the retired spelling asleep, and it wakes up the day
 * somebody uncomments it. To write about the old spelling, put it inline in backticks
 * the way these docblocks do, not as a statement inside a block comment.
 */
function* girsRuntimeImports(source) {
    const lineOf = (index) => source.slice(0, index).split('\n').length;
    /**
     * A NAMESPACE module, as opposed to a data subpath.
     *
     * Two spellings reach the same namespace: the bare package, and the subpath that IS
     * the package — `@girs/adw-1/adw-1` is literally `import Adw from
     * 'gi://Adw?version=1'` inside, which the rolldown plugin's own comment records. The
     * first version of this rule said "bare package only" and therefore exempted the
     * second, which is the spelling that most needs converting; review caught it while
     * it was still latent, no such import existing in the tree yet.
     *
     * The back-reference is what keeps this a rule instead of a list: it says "the
     * subpath that repeats the package name", so `vocabulary`, `ambient` and `import`
     * fall out without being named, and so does the next data subpath ts-for-gir adds.
     */
    const isNamespaceModule = (specifier) =>
        /^@girs\/[^/]+$/.test(specifier) || /^@girs\/([^/]+)\/\1(\.js)?$/.test(specifier);

    // A static import statement, starting a line, with a clause that may span lines. The
    // clause cannot contain `;`, which is what stops the match from running past the end
    // of one statement into the `from` of a later `export … from`.
    const STATIC = /^[ \t]*import\s+(?!type\s)([^;]*?)\s*from\s*['"](@girs\/[^'"]+)['"]/gm;
    for (const match of source.matchAll(STATIC)) {
        const [, bindings, specifier] = match;
        if (!isNamespaceModule(specifier)) continue;
        // `import { type Widget, type Align }` binds no value; `import { Button }` does.
        const named = /^\{([\s\S]*)\}$/.exec(bindings.trim());
        if (named !== null) {
            const bindsValue = named[1]
                .split(',')
                .map((entry) => entry.trim())
                .filter((entry) => entry.length > 0)
                .some((entry) => !entry.startsWith('type '));
            if (!bindsValue) continue;
        }
        // Whitespace collapsed rather than the first line taken: a wrapped list reported
        // as `import {` names nothing a reader can act on.
        yield { line: lineOf(match.index), specifier, text: match[0].trim().replace(/\s+/g, ' ') };
    }

    // A dynamic import, anywhere in an expression.
    const DYNAMIC = /\bimport\s*\(\s*['"](@girs\/[^'"]+)['"]\s*\)/g;
    for (const match of source.matchAll(DYNAMIC)) {
        const specifier = match[1];
        if (!isNamespaceModule(specifier)) continue;
        const lineStart = source.lastIndexOf('\n', match.index) + 1;
        const before = source.slice(lineStart, match.index);
        if (before.includes('//') || before.trimStart().startsWith('*')) continue;
        yield {
            line: lineOf(match.index),
            specifier,
            text: source.slice(lineStart, match.index + match[0].length).trim(),
        };
    }
}

// SELF-TEST FIRST. A reader whose pattern stopped matching would report zero offenders
// and print OK over a tree full of them, which is the failure this file exists to make
// impossible.
const selfTestFailures = [];
for (const [source, expected] of GIRS_RUNTIME_IMPORT_VECTORS) {
    const found = [...girsRuntimeImports(source)].map((entry) => entry.specifier);
    if (JSON.stringify(found) !== JSON.stringify(expected)) {
        selfTestFailures.push(
            `  ${JSON.stringify(source)}\n    expected ${JSON.stringify(expected)}, got ${JSON.stringify(found)}`,
        );
    }
}
if (selfTestFailures.length > 0) {
    process.stderr.write(
        `check-girs-runtime-imports: the reader failed its own vectors:\n${selfTestFailures.join('\n')}\n`,
    );
    process.exit(1);
}

const files = execSync('git ls-files', { encoding: 'utf8' })
    .split('\n')
    .filter((file) => file.length > 0 && SOURCE.test(file) && !GENERATED.test(file) && file !== FIXTURES);

const offenders = [];
const pendingHits = new Map(PENDING.map((prefix) => [prefix, 0]));
let scanned = 0;

for (const file of files) {
    let source;
    try {
        source = readFileSync(file, 'utf8');
    } catch {
        continue; // a tracked path that is not readable here (gitlink, dangling symlink)
    }
    if (!source.includes('@girs/')) continue;
    scanned++;
    for (const found of girsRuntimeImports(source)) {
        const prefix = PENDING.find((candidate) => file.startsWith(candidate));
        if (prefix === undefined) offenders.push(`${file}:${found.line}: ${found.text}`);
        else pendingHits.set(prefix, pendingHits.get(prefix) + 1);
    }
}

const stale = [...pendingHits.entries()].filter(([, hits]) => hits === 0).map(([prefix]) => prefix);
const remaining = [...pendingHits.values()].reduce((sum, hits) => sum + hits, 0);

if (offenders.length > 0) {
    process.stderr.write(
        `check-girs-runtime-imports: ${offenders.length} runtime import(s) of the type vocabulary:\n\n`,
    );
    for (const offender of offenders) process.stderr.write(`  ${offender}\n`);
    process.stderr.write(
        '\n`@girs/*` has no runtime. Reach the library through the loader instead:\n' +
            "  import Gtk from 'gi://Gtk?version=4.0';\n" +
            "  import Adw from 'gi://Adw?version=1';\n\n" +
            'A type-only use keeps `@girs/*` and says so:\n' +
            "  import type Gtk from '@girs/gtk-4.0';\n",
    );
    process.exit(1);
}

if (stale.length > 0) {
    process.stderr.write(
        `check-girs-runtime-imports: ${stale.length} PENDING entr(ies) in this script have no offenders left:\n\n` +
            stale.map((prefix) => `  ${prefix}\n`).join('') +
            '\nDelete them from PENDING. An exemption that outlives the thing it exempts is\n' +
            'what turns a migration list into a permanent one.\n',
    );
    process.exit(1);
}

process.stdout.write(
    `check-girs-runtime-imports: OK — ${GIRS_RUNTIME_IMPORT_VECTORS.length} self-test vector(s); ` +
        `${scanned} file(s) mention \`@girs/\`, ${remaining} runtime import(s) left in ${PENDING.length} pending director(ies).\n`,
);
